db:insert.db:sql:
INSERT INTO shipment_tracking_events (
    event_key, event_id, shipment_id, tracking_number, carrier,
    original_status, normalized_status, event_timestamp, received_timestamp,
    location, description, processing_result, correlation_id, source_payload
) VALUES (
    :eventKey, :eventId, :shipmentId, :trackingNumber, :carrier,
    :originalStatus, :normalizedStatus, :eventTimestamp, :receivedTimestamp,
    :location, :description, :processingResult, :correlationId, :sourcePayload
);

INSERT INTO notification_outbox (
    notification_id, shipment_id, tracking_number, carrier, milestone,
    message_body, channels, status, correlation_id
) VALUES (
    :notificationId, :shipmentId, :trackingNumber, :carrier, :milestone,
    :messageBody, :channels, 'QUEUED', :correlationId
)
ON DUPLICATE KEY UPDATE status = 'QUEUED';

db:update.db:input-parameters:
#[%dw 2.0
output application/java
---
{
	notificationId: vars.notificationItem.notificationId default payload.notificationId
}]

db:insert.db:sql:
INSERT INTO integration_alerts (
    alert_id, alert_type, severity, tracking_number, carrier, alert_message, correlation_id
) VALUES (
    :alertId, :alertType, :severity, :trackingNumber, :carrier, :alertMessage, :correlationId
);
